import { useEffect, useState } from "react";
import { apiFetch, readableError } from "../../../lib/api";
import { Button } from "../../../components/signal/Signal";
import { qualifiedRef } from "../../api";
import { useDesk } from "../../store";
import { SurfaceLedger, SurfaceLedgerRow, SurfaceState } from "../../surface/Surface";
import { countLabel } from "../../surface/count";
import { MicButton } from "../../surface";
import { StringGadget } from "../../surface/gadgets";

type ReceiptSource = {
  source_type: string;
  source_ref: string;
  text?: string;
  speaker?: string;
  meeting_id?: string;
};

type ReceiptWork = { id: string; work_type: string; work_ref: string };
type ReceiptRevision = {
  id: string;
  field_name: string;
  old_value: string | null;
  new_value: string | null;
  created_at: string;
};

type Receipt = {
  id: string;
  decision_text: string;
  rationale: string | null;
  alternatives: string | null;
  owner: string | null;
  review_date: string | null;
  lifecycle: string;
  sources?: ReceiptSource[];
  work?: ReceiptWork[];
  revisions?: ReceiptRevision[];
  predecessor_id?: string | null;
  successor_id?: string | null;
};

function receiptStatus(receipt: Receipt): "governing" | "superseded" | "related" {
  if (receipt.lifecycle === "active") return "governing";
  if (receipt.lifecycle === "superseded") return "superseded";
  return "related";
}

function shortId(id: string): string {
  return id.replace(/^record-/, "").slice(0, 12);
}

function humanDate(value: string | null | undefined): string {
  if (!value) return "—";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString();
}

/** Search-first, in-place decision history for the Intelligence pullout. */
export function DecisionsView({
  initialQuery = "",
  initialWhyOnly = false,
  workRef,
  receiptId,
}: {
  initialQuery?: string;
  initialWhyOnly?: boolean;
  workRef?: string;
  receiptId?: string;
}) {
  const openPullout = useDesk((state) => state.openPullout);
  const [query, setQuery] = useState(initialQuery);
  const [whyOnly, setWhyOnly] = useState(initialWhyOnly);
  const [results, setResults] = useState<Receipt[]>([]);
  const [selected, setSelected] = useState<Receipt | null>(null);
  const [loading, setLoading] = useState(true);
  const [detailLoading, setDetailLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    setQuery(initialQuery);
    setWhyOnly(initialWhyOnly);
  }, [initialQuery, initialWhyOnly]);

  useEffect(() => {
    let current = true;
    const timer = window.setTimeout(() => {
      setLoading(true);
      setError("");
      const [workType, ...workRefParts] = workRef?.split(":") ?? [];
      const linkedWorkRef = workRefParts.join(":");
      const endpoint = workType && linkedWorkRef
        ? `/api/decision-records/work/${encodeURIComponent(workType)}/${encodeURIComponent(linkedWorkRef)}`
        : query.trim()
          ? `/api/decision-records/search?q=${encodeURIComponent(query.trim())}`
          : "/api/decision-records";
      void apiFetch<Receipt[]>(endpoint)
        .then((receipts) => {
          if (current) setResults(Array.isArray(receipts) ? receipts : []);
        })
        .catch((reason) => {
          if (current) {
            setResults([]);
            setError(readableError(reason));
          }
        })
        .finally(() => {
          if (current) setLoading(false);
        });
    }, query.trim() ? 200 : 0);
    return () => {
      current = false;
      window.clearTimeout(timer);
    };
  }, [query, workRef]);

  const visibleResults = whyOnly
    ? results.filter((receipt) => receiptStatus(receipt) === "governing")
    : results;

  const openReceipt = (receiptId: string) => {
    setDetailLoading(true);
    setError("");
    void apiFetch<Receipt>(`/api/decision-records/${encodeURIComponent(receiptId)}`)
      .then(setSelected)
      .catch((reason) => setError(readableError(reason)))
      .finally(() => setDetailLoading(false));
  };

  useEffect(() => {
    if (receiptId) openReceipt(receiptId);
  }, [receiptId]);

  const openSource = (source: ReceiptSource) => {
    const meetingId = source.meeting_id ?? (source.source_type === "meeting" ? source.source_ref : "");
    if (meetingId) openPullout(qualifiedRef("meeting", meetingId));
  };

  if (selected || detailLoading) {
    return (
      <ReceiptDetail
        receipt={selected}
        loading={detailLoading}
        error={error}
        onBack={() => {
          setSelected(null);
          setError("");
        }}
        onOpenReceipt={openReceipt}
        onOpenSource={openSource}
        onOpenWork={(work) => openPullout(qualifiedRef(work.work_type, work.work_ref))}
      />
    );
  }

  return (
    <div className="receipts-view">
      <div className="receipts-search">
        <span className="receipts-search-prefix" aria-hidden="true">WHY</span>
        <StringGadget
          label="Search decisions"
          type="search"
          value={query}
          onChange={setQuery}
          placeholder="Search decisions"
        />
        <MicButton onText={setQuery} />
      </div>
      <div className="receipts-search-actions">
        <Button
          variant="ghost"
          dense
          className={`receipts-why-filter${whyOnly ? " is-active" : ""}`}
          aria-pressed={whyOnly}
          onClick={() => setWhyOnly((value) => !value)}
        >
          WHY ONLY
        </Button>
        {whyOnly ? <span>GOVERNING DECISIONS</span> : <span>ALL DECISIONS</span>}
      </div>
      {error ? <SurfaceState error={error} /> : null}
      <SurfaceLedger cols="facts" count={countLabel("DECISIONS", visibleResults.length)}>
        {loading ? (
          <SurfaceState loading />
        ) : visibleResults.length ? (
          <ul className="surface-ledger-rows receipts-results">
            {visibleResults.map((receipt) => {
              const status = receiptStatus(receipt);
              return (
                <SurfaceLedgerRow
                  key={receipt.id}
                  primary={receipt.decision_text}
                  lineLabel={`Open decision ${receipt.decision_text}`}
                  onToggle={() => openReceipt(receipt.id)}
                  cells={
                    <>
                      <span className="surface-ledger-cell receipts-id">D-{shortId(receipt.id)}</span>
                      <span className="surface-ledger-cell">{receipt.owner || "UNASSIGNED"}</span>
                      <span className="surface-ledger-cell">
                        <span className="surface-token" data-tone={status === "superseded" ? "muted" : "ok"}>
                          {status.toUpperCase()}
                        </span>
                      </span>
                    </>
                  }
                />
              );
            })}
          </ul>
        ) : (
          <SurfaceState empty emptyLabel={whyOnly ? "No governing decisions." : "No decisions match this search."} />
        )}
      </SurfaceLedger>
    </div>
  );
}

function ReceiptDetail({
  receipt,
  loading,
"""Durable decision record operations (HS-127-01)."""

from __future__ import annotations

import json
from datetime import UTC, date, datetime
from typing import Any
from uuid import uuid4

from holdspeak.principals import PrincipalRight
from holdspeak.services.brief_carry import require_right
from holdspeak.services.observer import (
    NullObserver,
    PipelineObserver,
    current_correlation_id,
    observe_service,
)
from holdspeak.services.service_event_ledger import ServiceEventLedger


_SOURCE_TYPES = frozenset({"meeting", "desk"})
#: HS-200-13: the record lifecycles.  ``active`` / ``published`` are CURRENT;
#: ``superseded`` names a successor; ``disputed`` is contested -- discoverable
#: on recall, never presented as current, never accented (story 13 AC2).
#: ``disputed`` is defined minimally here: a verb, a reason, a revision row;
#: no resolution workflow (out of scope: enterprise approval).
LIFECYCLES = frozenset({"active", "superseded", "published", "disputed"})
CURRENT_LIFECYCLES = frozenset({"active", "published"})
#: A supersession may seal an active OR a disputed predecessor (the usual
#: way a dispute ends is a newer decision).
_SUPERSEDABLE = frozenset({"active", "disputed"})
_EDITABLE_FIELDS = frozenset(
    {"decision_text", "rationale", "alternatives", "owner", "review_date"}
)


@observe_service
class DecisionRecordService:
    """Create and retrieve the durable canon for a decision."""

    def __init__(self, db: Any, *, observer: PipelineObserver | None = None) -> None:
        self._db = db
        self._observer = observer or NullObserver()

    def create(
        self,
        principal: Any,
        *,
        decision_text: str,
        rationale: str | None = None,
        alternatives: str | None = None,
        owner: str | None = None,
        review_date: str | None = None,
        source_type: str,
        source_id: str,
    ) -> dict[str, Any]:
        """Create a new decision record."""
        text = self._required("decision_text", decision_text)
        source_kind = self._required("source_type", source_type)
        if source_kind not in _SOURCE_TYPES:
            raise ValueError("source_type must be 'meeting' or 'desk'")
        source = self._required("source_id", source_id)
        record_id = f"record-{uuid4().hex}"
        now = datetime.now(UTC).isoformat()

        with self._db._connection() as conn:
            conn.execute(
                """INSERT INTO decision_records
                   (id, decision_text, rationale, alternatives, owner, review_date,
                    source_type, source_id, created_at, updated_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    record_id,
                    text,
                    rationale,
                    alternatives,
                    owner,
                    review_date,
                    source_kind,
                    source,
                    now,
                    now,
                ),
            )
            row = conn.execute(
                "SELECT * FROM decision_records WHERE id = ? AND deleted = 0", (record_id,)
            ).fetchone()
        assert row is not None
        return self._record_dict(row)

    def create_from_meeting(self, principal: Any, decision_id: str) -> dict[str, Any]:
        """Mint a record from a meeting-derived decision."""
        decision = self._db.decisions.get(decision_id)
        if decision is None:
            raise KeyError(str(decision_id or "").strip())
        existing = self._record_for_source("meeting", decision.id)
        if existing is not None:
            return existing

        record = self.create(
            principal,
            decision_text=decision.text,
            rationale=decision.rationale,
            source_type="meeting",
            source_id=decision.id,
        )
        # A segment is precision evidence, not a prerequisite for minting the
        # record.  Keep its absence honest when the decision's moment cannot
        # be resolved from the current transcript.
        try:
            moment = self._db.decisions.resolve_decision_moment(decision.id)
        except Exception:
            moment = None
        sources: list[tuple[str, str]] = [
            ("meeting", decision.source_meeting_id),
            ("artifact", decision.source_artifact_id),
        ]
        if moment is not None:
            sources.append(("segment", str(moment.segment_id)))
        self._add_sources(record["id"], tuple(sources))
        return record

    def create_from_desk(self, principal: Any, desk_decision_id: str) -> dict[str, Any]:
        """Mint a record from an authored desk decision."""
        decision = self._db.desk_decisions.get(desk_decision_id)
        if decision is None:
            raise KeyError(str(desk_decision_id or "").strip())
        existing = self._record_for_source("desk", decision.id)
        if existing is not None:
            return existing

        decision_text = decision.decision_markdown.strip()
        if not decision_text:
            raise ValueError("desk decision decision_markdown is required")
        rationale = self._join_text(
            decision.context_markdown, decision.consequences_markdown
        )
        alternatives = self._alternatives_text(decision.alternatives_json)
        owner = ", ".join(decider.strip() for decider in decision.deciders if decider.strip())
        return self.create(
            principal,
            decision_text=decision_text,
            rationale=rationale or None,
